class Calculator {
  def add(a: Int, b: Int): Int = {
    val sum = a + b
    sum
  }

  def multiply(a: Int, b: Int) = a * b
}

object Main {
  def main(args: Array[String]): Unit = {
    val calc = new Calculator
    println(calc.add(2, 3))
    println(calc.multiply(4, 5))
  }
}

