class Greeter {
  def greeting(name: String): String = s"Hello, $name!"

  def shout(name: String): String = greeting(name).toUpperCase
}

object Main {
  def main(args: Array[String]): Unit = {
    val g = new Greeter
    println(g.greeting("Ada"))
    println(g.shout("Ada"))
    println(s"${2 + 3} letters")
  }
}

